begin;
select plan(28);
select has_table('public','trips','trips exists');
select has_table('public','trip_vehicle_assignments','vehicle history exists');
select has_table('public','trip_seats','trip seat snapshot exists');
select has_view('public','public_trip_catalog','public projection exists');
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values('12000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','phase3@example.test','x',now(),'{}','{}',now(),now());
insert into public.accounts(id,legal_name) values('22000000-0000-0000-0000-000000000001','Conta Phase 3');
insert into public.agencies(id,account_id,name) values('32000000-0000-0000-0000-000000000001','22000000-0000-0000-0000-000000000001','Agência Phase 3'),('32000000-0000-0000-0000-000000000002','22000000-0000-0000-0000-000000000001','Outra Agência');
insert into public.licenses(account_id,agency_id,status) values('22000000-0000-0000-0000-000000000001','32000000-0000-0000-0000-000000000001','ACTIVE'),('22000000-0000-0000-0000-000000000001','32000000-0000-0000-0000-000000000002','ACTIVE');
insert into public.agency_members(agency_id,user_id,role) values('32000000-0000-0000-0000-000000000001','12000000-0000-0000-0000-000000000001','ADMIN');
insert into public.passenger_categories(id,agency_id,name,min_age,max_age,occupies_seat_default) values('42000000-0000-0000-0000-000000000001','32000000-0000-0000-0000-000000000001','Criança',3,11,true);
set local role authenticated; select set_config('request.jwt.claim.sub','12000000-0000-0000-0000-000000000001',true);
select lives_ok($$insert into public.trips(id,agency_id,code,title,slug,destination,departure_at,return_at,created_by,status) values('52000000-0000-0000-0000-000000000001','32000000-0000-0000-0000-000000000001','TRIP-001','Viagem íntegra','viagem-integra','Destino',now()+interval '30 days',now()+interval '32 days','12000000-0000-0000-0000-000000000001','SALES_OPEN')$$,'admin creates trip');
select throws_ok($$insert into public.trips(agency_id,code,title,slug,destination,departure_at,return_at,created_by) values('32000000-0000-0000-0000-000000000002','X','Outra viagem','outra','Destino',now()+interval '30 days',now()+interval '31 days','12000000-0000-0000-0000-000000000001')$$,'42501',null,'tenant isolation blocks cross agency trip');
insert into public.trip_content(agency_id,trip_id,description,included_items) values('32000000-0000-0000-0000-000000000001','52000000-0000-0000-0000-000000000001','Conteúdo público',array['transporte']);
insert into public.trip_itinerary_items(agency_id,trip_id,day_number,title) values('32000000-0000-0000-0000-000000000001','52000000-0000-0000-0000-000000000001',1,'Saída');
insert into public.trip_passenger_prices(agency_id,trip_id,passenger_category_id,list_price,minimum_price_without_approval,occupies_seat) values('32000000-0000-0000-0000-000000000001','52000000-0000-0000-0000-000000000001','42000000-0000-0000-0000-000000000001',100.10,90.05,true);
select is((select list_price::text from public.trip_passenger_prices),'100.10','money remains exact numeric');
select ok((select occupies_seat from public.trip_passenger_prices),'seat occupancy is independent from price');
select is(public.age_on_date('2014-09-16','2026-09-15'),11,'age is calculated on departure date before birthday');
select is(public.age_on_date('2014-09-15','2026-09-15'),12,'age changes on birthday at departure');
select is((select category_id from public.trip_price_for_birth_date('52000000-0000-0000-0000-000000000001','2018-01-01')),'42000000-0000-0000-0000-000000000001'::uuid,'trip price category uses age at departure');
insert into public.transport_suppliers(id,agency_id,name) values('62000000-0000-0000-0000-000000000001','32000000-0000-0000-0000-000000000001','Fornecedor');
insert into public.vehicle_templates(id,agency_id,name,capacity) values('72000000-0000-0000-0000-000000000001','32000000-0000-0000-0000-000000000001','Ônibus A',2),('72000000-0000-0000-0000-000000000002','32000000-0000-0000-0000-000000000001','Ônibus B',3);
insert into public.vehicle_template_seats(agency_id,vehicle_template_id,label) values('32000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000001','1A'),('32000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000001','1B'),('32000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000002','1A');
select isnt(public.assign_trip_vehicle('52000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000001','62000000-0000-0000-0000-000000000001','Inicial'),null,'vehicle assignment created');
select is((select count(*) from public.trip_seats),2::bigint,'seat map is snapshotted');
select isnt(public.assign_trip_vehicle('52000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000002','62000000-0000-0000-0000-000000000001','Troca'),null,'vehicle replacement creates assignment');
select is((select count(*) from public.trip_vehicle_assignments),2::bigint,'vehicle history is preserved');
select is((select count(*) from public.trip_vehicle_assignments where ended_at is null),1::bigint,'only one current vehicle');
select ok((select bool_and(requires_review) from public.trip_seats where assignment_id=(select id from public.trip_vehicle_assignments where ended_at is null)),'incompatible replacement map requires review');
select lives_ok($$insert into public.trip_costs(agency_id,trip_id,category,description,cost_type,allocation_type,estimated_amount) values('32000000-0000-0000-0000-000000000001','52000000-0000-0000-0000-000000000001','TRANSPORT','Ônibus','FIXED','SHARED',1234.56)$$,'trip cost saves with exact domain types');
insert into public.site_trip_publications values('32000000-0000-0000-0000-000000000001','52000000-0000-0000-0000-000000000001','PUBLISHED',now(),now());
select is((select count(*) from public.public_trip_catalog),1::bigint,'published trip appears in public projection');
update public.site_trip_publications set status='UNPUBLISHED';
select is((select status from public.trips),'SALES_OPEN'::public.trip_status,'unpublish does not change trip lifecycle');
select is((select count(*) from public.public_trip_catalog),0::bigint,'unpublished trip leaves catalog');
select isnt(public.duplicate_trip('52000000-0000-0000-0000-000000000001','TRIP-002','viagem-copia'),null,'trip duplicates transactionally');
select is((select count(*) from public.trips),2::bigint,'duplicate creates only one new trip');
select is((select count(*) from public.trip_vehicle_assignments where trip_id<>(select id from public.trips where code='TRIP-001')),0::bigint,'duplicate does not copy occupancy or vehicle history');
select is((select contract_pending from public.trips where code='TRIP-002'),true,'duplicate remains contract pending');
select throws_ok($$insert into public.trip_images(agency_id,trip_id,storage_path,mime_type,size_bytes,alt_text) values('32000000-0000-0000-0000-000000000001','52000000-0000-0000-0000-000000000001','bad/path.exe','application/octet-stream',20,'x')$$,'23514',null,'unsafe upload metadata is rejected');
reset role;
select hasnt_column('public','public_trip_catalog','insurance_included','public catalog does not imply insurance');
select hasnt_column('public','public_trip_catalog','estimated_amount','public catalog excludes costs');
select * from finish(); rollback;
